// === Tab: mySketch ===
let texture;

function preload() {
  texture = loadImage("https://openprocessing.org/sketch/2601413/files/texture.jpg");
}

function setup() {
  createCanvas(windowWidth, windowHeight);
  noLoop();
  generateCactus();
}

function draw() {
  // Nothing needed here
}

function mousePressed() {
  generateCactus();
}

function generateCactus() {
  background("#E9E6DB"); // Clear with background color

  const w = 200;
  const h = 70;

  // Sand texture dots
  for (let i = 0; i < 140000; i++) {
    const t = 1;
    const r = pow(random(0, pow(10, t)), 1 / t) / 10;
    stroke("#877E75");
    strokeWeight(random(1));
    const a = random(TWO_PI);
    const x = width / 2 + cos(a) * w * r;
    const y = height / 2 + sin(a) * h * r;
    const yOffset = sin(r * 50) * (1 - r) * 5;
    point(x, y + yOffset);
  }

  for (let i = 0; i < 140000; i++) {
    var t = -1;
    var r = pow(random(0, pow(10, t)), 1 / t) / 10;
    stroke("#877E75");
    strokeWeight(random(1));
    var a = random(TWO_PI);
    var x = width / 2 + cos(a) * w * r;
    var y = height / 2 + sin(a) * h * r;
    var yOffset = sin(r * 50) * (1 - r) * 5;
    point(x, y + yOffset);
  }

  // Draw cactus
  bunnyEarCactus(
    width / 2,
    height / 2,
    random(40, 60),
    random(60, 100),
    0,
    random([3, 4])
  );

  // Overlay texture softly (no multiply!)
  tint(255, 40); // Transparent white (subtle effect)
  image(texture, 0, 0, width, height);
}

async function bunnyEarCactusLeaf(x, y, w, h) {
  fill("#C3CDBE");
  noStroke();
  ellipse(0, -h * 0.4, w, h);

  strokeWeight(1);
  for (let i = 0; i < w * h * 0.5; i++) {
    var a = random(TWO_PI);
    var r = 1 - random(random());
    colorMode(HSB);
    stroke(randomGaussian(109, 10), randomGaussian(10, 10), randomGaussian(60, 20));
    point(cos(a) * w * r / 2, sin(a) * h * r / 2 - h * 0.4);
  }

  for (let i = 0; i < w * h * 0.5; i++) {
    var a = random(TWO_PI);
    var r = 1 - random(random(random()));
    colorMode(HSB);
    stroke(randomGaussian(109, 10), randomGaussian(30, 10), randomGaussian(50, 20));
    point(cos(a) * w * r / 2, sin(a) * h * r / 2 - h * 0.4);
  }
}

async function bunnyEarCactus(x, y, w, h, rAngle, step) {
  push();
  colorMode(HSB);
  translate(x, y);
  strokeWeight(2);
  rotate(rAngle);
  bunnyEarCactusLeaf(x, y, w, h);
  point(0, 0);

  if ((step > 0 && random() < 0.7) || step >= 3) {
    translate(0, -h * 0.4);
    point(0, 0);
    if (random() < 0.5) {
      bunnyEarCactus(
        cos(-PI / 2 + 1) * w / 2,
        sin(-PI / 2 + 1) * h / 2,
        w * random(0.7, 0.9),
        h * random(0.7, 0.9),
        random(1, 0),
        step - 1
      );
      bunnyEarCactus(
        cos(-PI / 2 - 1) * w / 2,
        sin(-PI / 2 - 1) * h / 2,
        w * random(0.7, 0.9),
        h * random(0.7, 0.9),
        random(-1, 0),
        step - 1
      );
    } else {
      bunnyEarCactus(
        0,
        -h * 0.4,
        w * random(0.7, 0.9),
        h * random(0.7, 0.9),
        random(-0.5, 0.5),
        step - 1
      );
    }
  }

  pop();
}

